DROP TABLE IF EXISTS `symbiosis_neighbor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `symbiosis_neighbor` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `symbiosis_result_id` int(11) NOT NULL,
  `name` varchar(300) DEFAULT NULL,
  `sector` varchar(100) DEFAULT NULL,
  `lat` float DEFAULT NULL,
  `lon` float DEFAULT NULL,
  `complementarity_pct` int(11) DEFAULT NULL,
  `annual_kwh` float DEFAULT NULL,
  `distance_km` float DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `source` varchar(50) DEFAULT NULL,
  `is_registered` tinyint(1) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `symbiosis_result_id` (`symbiosis_result_id`),
  CONSTRAINT `symbiosis_neighbor_ibfk_1` FOREIGN KEY (`symbiosis_result_id`) REFERENCES `symbiosis_result` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=364 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

